{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aisdlc.dev/schemas/requirement.schema.json",
  "title": "AI SDLC Requirements Document",
  "type": "object",
  "additionalProperties": false,
  "required": ["intent_id", "functional_requirements", "non_functional_requirements", "acceptance_criteria", "success_criteria"],
  "properties": {
    "schema_version": {"type": "integer", "minimum": 0, "description": "Record schema generation. Absent means 0: a record written before schema versioning existed."},
    "intent_id": {"type": "string", "pattern": "^I[0-9]{3,}$"},
    "functional_requirements": {"type": "array", "items": {"$ref": "#/$defs/functionalRequirement"}},
    "non_functional_requirements": {"type": "array", "items": {"$ref": "#/$defs/nonFunctionalRequirement"}},
    "acceptance_criteria": {"type": "array", "items": {"$ref": "#/$defs/criterion"}},
    "success_criteria": {"type": "array", "items": {"$ref": "#/$defs/success"}},
    "contracts": {
      "type": "array",
      "description": "Interface contracts under 02-specification/ this Intent delivers. Every operation must be covered by a criterion's `contract_operations` or excluded with a reason.",
      "items": {"$ref": "#/$defs/contract"}
    },
    "glossary": {
      "type": "array",
      "description": "Domain terms defined for this specification. A term defined here is precise by declaration, so the quality lint does not flag it as ambiguous.",
      "items": {"$ref": "#/$defs/glossaryEntry"}
    }
  },
  "$defs": {
    "criterionRefs": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^AC-[0-9]{3,}$"}},
    "priority": {
      "enum": ["must", "should", "could", "wont"],
      "description": "MoSCoW. `wont` records scope explicitly excluded from this Intent: it needs no Task, and a Task that maps to it is scope growth."
    },
    "sources": {
      "type": "array",
      "description": "Where the requirement came from: a brief line, a stakeholder, a finding, or a decision.",
      "items": {"type": "string", "minLength": 1}
    },
    "compliance": {
      "type": "array",
      "description": "Controls this requirement implements, e.g. {framework: SOC2, control: CC6.1}.",
      "items": {
        "type": "object", "additionalProperties": false, "required": ["framework", "control"],
        "properties": {"framework": {"type": "string", "minLength": 1}, "control": {"type": "string", "minLength": 1}}
      }
    },
    "dataClassification": {"enum": ["public", "internal", "confidential", "restricted"]},
    "qualityCategory": {
      "description": "ISO/IEC 25010 quality characteristics, split where enterprise review asks about them separately.",
      "enum": [
        "performance", "scalability", "availability", "reliability", "security", "privacy", "compliance",
        "accessibility", "usability", "maintainability", "portability", "compatibility", "observability",
        "operability", "safety", "cost"
      ]
    },
    "measure": {
      "type": "object", "additionalProperties": false, "required": ["metric", "target"],
      "description": "The measurable form of a quality requirement: p95 latency <= 300 ms under 500 rps.",
      "properties": {
        "metric": {"type": "string", "minLength": 1},
        "target": {"type": ["number", "string"]},
        "unit": {"type": "string"},
        "condition": {"type": "string", "description": "Load, dataset, or environment the target holds under."}
      }
    },
    "functionalRequirement": {
      "type": "object", "additionalProperties": false, "required": ["id", "statement", "acceptance_criteria"],
      "properties": {
        "id": {"type": "string", "pattern": "^REQ-F-[0-9]{3,}$"},
        "statement": {"type": "string", "minLength": 1},
        "acceptance_criteria": {"$ref": "#/$defs/criterionRefs"},
        "priority": {"$ref": "#/$defs/priority"},
        "rationale": {"type": "string", "minLength": 1},
        "sources": {"$ref": "#/$defs/sources"},
        "compliance": {"$ref": "#/$defs/compliance"},
        "data_classification": {"$ref": "#/$defs/dataClassification"},
        "personal_data": {"type": "boolean"}
      }
    },
    "nonFunctionalRequirement": {
      "type": "object", "additionalProperties": false, "required": ["id", "statement", "acceptance_criteria"],
      "properties": {
        "id": {"type": "string", "pattern": "^REQ-NFR-[0-9]{3,}$"},
        "statement": {"type": "string", "minLength": 1},
        "acceptance_criteria": {"$ref": "#/$defs/criterionRefs"},
        "category": {"$ref": "#/$defs/qualityCategory"},
        "measure": {"$ref": "#/$defs/measure"},
        "wcag": {
          "type": "object", "additionalProperties": false, "required": ["version", "level"],
          "description": "Required when category is accessibility: the conformance target automated checks verify.",
          "properties": {
            "version": {"enum": ["2.1", "2.2"]},
            "level": {"enum": ["A", "AA", "AAA"]},
            "scope": {"type": "array", "items": {"type": "string", "minLength": 1}, "description": "Pages, routes, or components in scope."}
          }
        },
        "manual_audit": {
          "type": "object", "additionalProperties": false, "required": ["owner"],
          "description": "Who covers the WCAG success criteria automated checkers cannot decide. The audit itself is outside this lifecycle.",
          "properties": {"owner": {"type": "string", "minLength": 1}, "reference": {"type": "string"}}
        },
        "priority": {"$ref": "#/$defs/priority"},
        "rationale": {"type": "string", "minLength": 1},
        "sources": {"$ref": "#/$defs/sources"},
        "compliance": {"$ref": "#/$defs/compliance"},
        "data_classification": {"$ref": "#/$defs/dataClassification"},
        "personal_data": {"type": "boolean"}
      }
    },
    "criterion": {
      "type": "object", "additionalProperties": true, "required": ["id", "verification_class", "statement"],
      "properties": {
        "id": {"type": "string", "pattern": "^AC-[0-9]{3,}$"},
        "verification_class": {"enum": ["D", "S", "J", "N"]},
        "statement": {"type": "string", "minLength": 1},
        "given": {"type": "string", "minLength": 1},
        "when": {"type": "string", "minLength": 1},
        "then": {"type": "string", "minLength": 1},
        "contract_operations": {
          "type": "array", "minItems": 1,
          "description": "Contract operations this criterion verifies, as `<contract path>#<operationId>`.",
          "items": {"type": "string", "pattern": "^contracts/.+#.+$"}
        },
        "check": {"type": "string"},
        "eval": {"type": "string", "pattern": "^EVAL-[0-9]{3,}$"},
        "dataset": {"type": "string"},
        "metric": {"type": "string"},
        "threshold": {},
        "minimum_sample_size": {"type": "integer", "minimum": 1},
        "tolerance_band": {"type": "number", "minimum": 0}
      }
    },
    "success": {
      "type": "object", "additionalProperties": false, "required": ["id", "statement"],
      "properties": {
        "id": {"type": "string", "pattern": "^SC-[0-9]{3,}$"},
        "statement": {"type": "string", "minLength": 1},
        "acceptance_criteria": {"$ref": "#/$defs/criterionRefs"},
        "brief_measure": {"type": "string", "minLength": 1, "description": "The Gate 1 success measure this criterion demonstrates, quoted from the brief."}
      }
    },
    "contract": {
      "type": "object", "additionalProperties": false, "required": ["path"],
      "properties": {
        "path": {"type": "string", "pattern": "^contracts/", "description": "Relative to 02-specification/."},
        "kind": {"enum": ["openapi", "asyncapi", "jsonschema"], "description": "Detected from the document when omitted."},
        "api": {
          "type": "string", "pattern": "^[a-z0-9][a-z0-9._-]*$",
          "description": "S3.3: stable identity across Intents. Contracts sharing an `api` are one interface, checked for concurrent change and for breaking change against the last completed Intent."
        },
        "breaking_changes_accepted": {
          "type": "array",
          "description": "S3.3: operations whose breaking change against the baseline is a decision, with a name and a reason.",
          "items": {
            "type": "object", "additionalProperties": false, "required": ["operation", "accepted_by", "reason"],
            "properties": {"operation": {"type": "string", "minLength": 1}, "accepted_by": {"type": "string", "minLength": 1}, "reason": {"type": "string", "minLength": 1}}
          }
        },
        "excluded_operations": {
          "type": "array",
          "items": {
            "type": "object", "additionalProperties": false, "required": ["operation", "reason"],
            "properties": {"operation": {"type": "string", "minLength": 1}, "reason": {"type": "string", "minLength": 1}}
          }
        }
      }
    },
    "glossaryEntry": {
      "type": "object", "additionalProperties": false, "required": ["term", "definition"],
      "properties": {"term": {"type": "string", "minLength": 1}, "definition": {"type": "string", "minLength": 1}}
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aisdlc.dev/schemas/threat-model.schema.json",
  "title": "AI SDLC Threat Model",
  "description": "STRIDE per trust boundary (Wave S2.2). Lives in 02-specification/, so it is frozen at Gate 2 and covered by the pre-gate review hash.",
  "type": "object",
  "additionalProperties": false,
  "required": ["intent_id", "boundaries", "threats"],
  "properties": {
    "schema_version": {"type": "integer", "minimum": 0},
    "intent_id": {"type": "string", "pattern": "^I[0-9]{3,}$"},
    "boundaries": {"type": "array", "minItems": 1, "items": {"$ref": "#/$defs/boundary"}},
    "threats": {"type": "array", "items": {"$ref": "#/$defs/threat"}}
  },
  "$defs": {
    "stride": {"enum": ["spoofing", "tampering", "repudiation", "information_disclosure", "denial_of_service", "elevation_of_privilege"]},
    "boundary": {
      "type": "object", "additionalProperties": false, "required": ["id", "name"],
      "properties": {
        "id": {"type": "string", "pattern": "^TB-[0-9]{3,}$"},
        "name": {"type": "string", "minLength": 1},
        "description": {"type": "string"},
        "not_applicable": {
          "type": "array",
          "description": "STRIDE categories considered at this boundary and judged not to apply, each with a reason. Silence is not a judgement.",
          "items": {
            "type": "object", "additionalProperties": false, "required": ["category", "reason"],
            "properties": {"category": {"$ref": "#/$defs/stride"}, "reason": {"type": "string", "minLength": 1}}
          }
        }
      }
    },
    "threat": {
      "type": "object", "additionalProperties": false, "required": ["id", "boundary", "stride", "description", "disposition"],
      "properties": {
        "id": {"type": "string", "pattern": "^TM-[0-9]{3,}$"},
        "boundary": {"type": "string", "pattern": "^TB-[0-9]{3,}$"},
        "stride": {"$ref": "#/$defs/stride"},
        "description": {"type": "string", "minLength": 1},
        "disposition": {"enum": ["mitigate", "accept", "transfer"]},
        "mitigated_by": {"type": "array", "items": {"type": "string", "pattern": "^REQ-(F|NFR)-[0-9]{3,}$"}},
        "verified_by": {"type": "array", "items": {"type": "string", "pattern": "^AC-[0-9]{3,}$"}},
        "standing_checks": {
          "type": "array",
          "description": "Inherited W4.3 security checks that add assurance. Supplementary: they never replace a Class N criterion.",
          "items": {"type": "string", "minLength": 1}
        },
        "inherited_from": {"type": "string", "pattern": "^LESSON-[0-9]{3,}$", "description": "S3.4: the promoted threat lesson this entry answers."},
        "accepted_by": {"type": "string", "minLength": 1},
        "reason": {"type": "string", "minLength": 1}
      }
    }
  }
}

# Eval Design: {{INTENT_ID}}

Use this artifact when `contains_model_behavior` is true or any criterion uses Class S, J, or N.

## {{EVAL_ID}} — {{EVAL_NAME}} (Class {{S_OR_J_OR_N}})

- Owner: {{DATASET_OWNER}}
- Dataset and version: {{DATASET_PATH_AND_VERSION}}
- Dataset hash: {{SHA256}}
- Metric: {{METRIC}}
- Threshold operator: {{GREATER_THAN_OR_EQUAL|LESS_THAN_OR_EQUAL|EQUAL}}
- Threshold value: {{PREDECLARED_VALUE}}
- Minimum sample size: {{MINIMUM_SAMPLE_SIZE}}
- Tolerance band: {{TOLERANCE_BAND}}
- Model identifier: {{MODEL_ID}}
- Prompt version and hash: {{PROMPT_VERSION_AND_HASH}}
- Temperature: {{TEMPERATURE}}
- Seed: {{SEED_OR_PROVIDER_UNSUPPORTED}}
- Runs: 3 for S/J; declared suite run for N

For Class J, record the judge model, prompt hash, human-labeled calibration set, and required agreement of at least 0.85 (the runner's floor; a repository may raise it, never lower it). For Class N, define attacker success precisely and require zero successes.

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://aisdlc.dev/schemas/task.schema.json",
  "title": "AI SDLC Task",
  "type": "object",
  "additionalProperties": false,
  "required": ["id", "intent_id", "phase_id", "title", "status", "objective", "requirements", "source_findings", "depends_on", "affected_paths", "shared_resources", "inputs", "expected_outputs", "acceptance_criteria", "verification_commands", "parallelizable", "retry_limit"],
  "properties": {"schema_version": {"type": "integer", "minimum": 0, "description": "Record schema generation. Absent means 0: a record written before schema versioning existed."}, 
    "id": {"type": "string", "pattern": "^I[0-9]{3,}-P[0-9]{2,}-T[0-9]{3,}$"},
    "intent_id": {"type": "string", "pattern": "^I[0-9]{3,}$"},
    "phase_id": {"type": "string", "pattern": "^I[0-9]{3,}-P[0-9]{2,}$"},
    "title": {"type": "string", "minLength": 1}, "status": {"enum": ["pending", "ready", "in_progress", "verifying", "review", "verified", "retry", "blocked", "failed", "superseded", "merged", "reverted"]},
    "objective": {"type": "string", "minLength": 1},
    "requirements": {"type": "array", "items": {"type": "string", "pattern": "^REQ-(F|NFR)-[0-9]{3,}$"}},
    "source_decisions": {"type": "array", "items": {"type": "string", "pattern": "^I[0-9]{3,}-D[0-9]{3,}$"}, "description": "Architectural decisions this Task implements. The third of the three trace targets the repository rules require; see decision.schema.json."}, "source_findings": {"type": "array", "items": {"type": "string", "pattern": "^F-[0-9]{3,}$"}},
    "depends_on": {"type": "array", "items": {"type": "string", "pattern": "^I[0-9]{3,}-P[0-9]{2,}-T[0-9]{3,}$"}},
    "affected_paths": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}},
    "shared_resources": {"type": "array", "uniqueItems": true, "items": {"type": "string", "pattern": "^[a-z][a-z0-9_-]*:.+$"}},
    "inputs": {"type": "array", "items": {"type": "string"}}, "expected_outputs": {"type": "array", "minItems": 1, "items": {"type": "string"}},
    "acceptance_criteria": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": true, "required": ["id", "verification_class"], "properties": {"id": {"type": "string", "pattern": "^AC-[0-9]{3,}$"}, "verification_class": {"enum": ["D", "S", "J", "N"]}, "mutation_threshold": {"type": "number", "minimum": 0, "maximum": 1, "description": "Optional Class D companion. Surviving mutants become structured retry input."}, "baseline_ref": {"type": "string", "pattern": "^BASELINE-[0-9]{3,}$", "description": "Brownfield criteria are stated relative to a characterization baseline."}}}},
    "verification_commands": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}, "description": "Visible instruments. May be authored by the implementing agent."},
    "holdout_commands": {
      "type": "array",
      "items": {"type": "string", "minLength": 1},
      "description": "Held-out instruments, authored outside the implementing context. Proving a command ran is not proving it could have failed."
    },
    "holdout_authorship": {
      "type": "object",
      "required": ["authored_by", "context"],
      "properties": {
        "authored_by": {"type": "string", "minLength": 1},
        "context": {"enum": ["specification", "verifier", "human", "baseline", "inherited", "implementing"]},
        "authored_at": {"type": "string", "format": "date-time"}
      }
    },
    "holdout_waiver": {
      "type": "object",
      "required": ["reason", "approved_by"],
      "description": "Recorded exception when a Task genuinely admits no held-out instrument. A waiver is a decision with a name on it, not a silent omission.",
      "properties": {
        "reason": {"type": "string", "minLength": 1},
        "approved_by": {"type": "string", "minLength": 1},
        "approved_at": {"type": "string", "format": "date-time"}
      }
    },
    "migration": {
      "type": "object",
      "description": "Declared when a Task changes persistent state. Forward, rollback and invariant evidence are all ordinary Class D commands.",
      "properties": {
        "forward_command": {"type": "string", "minLength": 1},
        "rollback_command": {"type": "string", "minLength": 1},
        "invariant_commands": {"type": "array", "items": {"type": "string", "minLength": 1}},
        "irreversible": {"type": "boolean"},
        "irreversibility_accepted_by": {"type": "string", "minLength": 1},
        "drops_fields": {"type": "array", "items": {"type": "string", "minLength": 1}},
        "reads_fields": {"type": "array", "items": {"type": "string", "minLength": 1}}
      }
    },
    "execution_posture": {
      "type": "object",
      "properties": {
        "network_policy": {"type": "string"},
        "filesystem_scope": {"type": "string"},
        "credential_surface": {"type": "string"}
      }
    },
    "repository": {"type": "string", "minLength": 1, "description": "Participating repository identifier for a federated Intent."},
    "parallelizable": {"type": "boolean"}, "retry_limit": {"type": "integer", "minimum": 0}
  },
  "anyOf": [{"properties": {"requirements": {"minItems": 1}}}, {"properties": {"source_findings": {"minItems": 1}}}]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://aisdlc.dev/schemas/finding.schema.json", "title": "AI SDLC Finding", "type": "object", "additionalProperties": false,
  "required": ["id", "severity", "status", "source", "description", "evidence", "impact", "recommended_action", "introduced_stage", "detected_stage"],
  "properties": {"schema_version": {"type": "integer", "minimum": 0, "description": "Record schema generation. Absent means 0: a record written before schema versioning existed."}, "id": {"type": "string", "pattern": "^F-[0-9]{3,}$"}, "severity": {"enum": ["critical", "high", "medium", "low"]}, "status": {"enum": ["open", "resolved", "accepted", "escalated"]}, "source": {"type": "string"}, "requirement": {"type": "string"}, "acceptance_criteria": {"type": "array", "items": {"type": "string"}}, "description": {"type": "string"}, "evidence": {"type": "array", "items": {"type": "string"}}, "impact": {"type": "string"}, "recommended_action": {"type": "string"}, "introduced_stage": {"type": "integer", "minimum": 0, "maximum": 6}, "detected_stage": {"type": "integer", "minimum": 0, "maximum": 6}, "lesson_ref": {"type": "string"}, "repeat": {"type": "boolean"}}
}
